== V1__sheet.sql
-- A sheet is the unit everything else is kept under. A row is made the first time its id is loaded;
-- a sheet that has never been loaded has no row and starts empty.
CREATE TABLE sheet (
    id         VARCHAR(200) PRIMARY KEY,
    created_by VARCHAR(200) NOT NULL,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
== V2__sheet_today.sql
-- The sheet's own "today": every date decision and default date on the sheet uses it, never the
-- real clock. It starts as the real date the sheet is first loaded.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CAST(created_at AS DATE) WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
== V3__person.sql
-- People kept on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name       VARCHAR(200) NOT NULL,
    grade      VARCHAR(1)   NOT NULL,
    created_by VARCHAR(200) NOT NULL,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX person_sheet ON person (sheet_id, id);
== V4__person_name_unique.sql
-- A person's name is unique on the sheet, compared without regard to case. Names are stored trimmed.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
== V5__claim.sql
-- A person's claims: an amount (0.00 or more, two decimals), a date and a note (may be empty).
-- Listed newest first (by id).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(19, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(2000)  NOT NULL DEFAULT '',
    created_by VARCHAR(200)   NOT NULL,
    created_at TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
== V6__rate.sql
-- The sheet's rate for each grade: a percent (0.00 or more, two decimals). A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id   VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    grade      VARCHAR(1)     NOT NULL,
    pct        DECIMAL(19, 2) NOT NULL CHECK (pct >= 0),
    set_by     VARCHAR(200)   NOT NULL,
    set_at     TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (sheet_id, grade)
);
== V7__claim_status.sql
-- A claim's status: DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. Only OPEN and SETTLED
-- claims count toward the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL;
== V8__claim_number.sql
-- A claim's number: given when it is opened, the sheet's next (1, 2, ...), with no gaps and never
-- reused. A draft has none; voiding clears it. The sheet keeps the last number it gave.
ALTER TABLE sheet ADD COLUMN last_claim_number BIGINT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN number BIGINT;
== V9__claim_settled_due.sql
-- A settled claim's due, fixed when it is settled: its amount at its person's grade's rate then.
-- None while not settled, or when the grade had no rate (then the due stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(19, 2);
== V10__rate_from.sql
-- A rate can carry a from-date: a grade may have several rates, one per from-date, and a claim uses
-- the one whose from-date is the latest on or before its date. No from-date applies from the
-- beginning of time (at most one such rate per grade).
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_key);
== V11__claim_opened_by.sql
-- Who opened a claim: set when it is opened; none while a draft. The user who opened a claim
-- cannot settle it (four eyes).
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(200);
== V12__person_version.sql
-- A person's version: raised by every saved edit. An edit carries the version its form loaded and
-- is refused when someone else has saved the person since.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
== V13__statement.sql
-- A person's statements: how many have been taken, and the last one's due-total (text: two
-- decimals, or n/a) and date (the sheet's today when it was taken). None until the first.
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total VARCHAR(30);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A claim bound by its person's last statement: it shows and totals the figure it had then
-- (stated_due; none when it had none), until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);
== V14__period.sql
-- The sheet's periods: a name (unique on the sheet, compared without regard to case; stored trimmed)
-- and a from and to date, inclusive, from on or before to. No two periods on a sheet overlap (checked
-- when one is added). A claim belongs to the period whose dates contain its date, or to none.
CREATE TABLE period (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name       VARCHAR(200) NOT NULL,
    name_key   VARCHAR(200) GENERATED ALWAYS AS (LOWER(name)),
    from_date  DATE         NOT NULL,
    to_date    DATE         NOT NULL,
    created_by VARCHAR(200) NOT NULL,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
CREATE INDEX period_sheet_from ON period (sheet_id, from_date);
== V15__period_closed.sql
-- A closed period: its due-total is fixed at the moment it was closed (closed_total), and no claim
-- dated inside it can be added, edited, opened, settled or voided. Open until closed.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(19, 2);
ALTER TABLE period ADD COLUMN closed_by VARCHAR(200);
ALTER TABLE period ADD COLUMN closed_at TIMESTAMP;
== V16__person_retired.sql
-- The date a person is retired from (null: not retired). A person with the date set counts as
-- retired at once, whatever the date; their claims dated after it are refused.
ALTER TABLE person ADD COLUMN retired_from DATE;
== V17__person_held.sql
-- Whether a person is on hold: while held, their OPEN claims count in no live total (their own
-- claimed and due-total, the sheet's totals, a period's total); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
== V18__setting_role.sql
-- A sheet's settings, by key; a null value is blank (for clerk-limit: no limit). A key with no row is blank.
CREATE TABLE sheet_setting (
    sheet_id   VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting    VARCHAR(100) NOT NULL,
    val        VARCHAR(200),
    set_by     VARCHAR(200) NOT NULL,
    set_at     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (sheet_id, setting)
);
-- The role a user name has on a sheet: clerk or steward. A name with no row is a clerk.
CREATE TABLE sheet_role (
    sheet_id   VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name  VARCHAR(200) NOT NULL,
    role       VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    set_by     VARCHAR(200) NOT NULL,
    set_at     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (sheet_id, user_name)
);
== V19__person_patron.sql
-- The people a person names as their patrons on the sheet: each at most once, never themselves.
CREATE TABLE person_patron (
    sheet_id   VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id  BIGINT       NOT NULL REFERENCES person (id),
    patron_id  BIGINT       NOT NULL REFERENCES person (id),
    added_by   VARCHAR(200) NOT NULL,
    added_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (person_id, patron_id),
    CHECK (person_id <> patron_id)
);
== V20__person_grade.sql
-- A person's grade is dated: each grade they are given applies from its from-date, and a claim uses
-- the one whose from-date is the latest on or before its date. No from-date applies from the
-- beginning of time: the first grade a person was given. The list shows the grade in force on the
-- sheet's today.
CREATE TABLE person_grade (
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    grade     VARCHAR(1)   NOT NULL,
    from_date DATE,
    from_key  DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01')),
    set_by    VARCHAR(200) NOT NULL,
    set_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX person_grade_from ON person_grade (person_id, from_key);
INSERT INTO person_grade (sheet_id, person_id, grade, from_date, set_by)
    SELECT sheet_id, id, grade, NULL, created_by FROM person;
ALTER TABLE person DROP COLUMN grade;
== V21__claim_correction.sql
-- A claim with a negative amount is a correction of a SETTLED claim of the same person: it keeps
-- the number of the claim it corrects (none for any other claim). The amount may now be negative:
-- the column is rebuilt without its old 0-or-more check.
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(19, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD COLUMN corrects BIGINT;
== V22__claim_period_number.sql
-- A claim's number is now text: the sheet-wide number (1, 2, ...) or, while the sheet's
-- period-numbering-from setting is in force when it is opened, <period name>-<n> (X-<n> for a claim
-- in no period). A correction names the number of the claim it corrects in the same form.
ALTER TABLE claim ALTER COLUMN number SET DATA TYPE VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(220);
-- The last number given in each period's own sequence on a sheet; the key '' is the sequence of
-- claims in no period. Numbers are never reused, so the sheet keeps them past a claim's voiding.
CREATE TABLE sheet_period_number (
    sheet_id    VARCHAR(200) NOT NULL REFERENCES sheet (id),
    period_key  VARCHAR(200) NOT NULL,
    last_number BIGINT       DEFAULT 0 NOT NULL,
    PRIMARY KEY (sheet_id, period_key)
);
== V23__claim_list_seq.sql
-- A claim's place in its sheet's list, newest first: given when added and again when it is moved to
-- another person (so a moved claim is listed as its new person's newest). Ties fall back to the id.
ALTER TABLE claim ADD COLUMN list_seq BIGINT DEFAULT 0 NOT NULL;
UPDATE claim SET list_seq = id;
== V24__claim_due_by.sql
-- A claim's due-by, fixed when it is added: its date plus the terms of its person's grade in force on
-- its date (a grade's own terms, setting terms-<grade>, else the sheet's terms). It does not change
-- when the terms or its date change later. Claims already added take their date plus the sheet's
-- terms now (14 when never set).
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD(DAY, COALESCE((SELECT CAST(s.val AS INT) FROM sheet_setting s
    WHERE s.sheet_id = claim.sheet_id AND s.setting = 'terms'), 14), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V25__claim_log.sql
-- A claim's status log: one line per status it has had (DRAFT when it was added, then each change),
-- with who made the change, the sheet's today then, and the claim's due as computed at that moment
-- (none: n/a). Listed oldest first (by id). Claims added before the log have no lines.
CREATE TABLE claim_log (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    claim_id BIGINT         NOT NULL REFERENCES claim (id),
    status   VARCHAR(10)    NOT NULL,
    by_user  VARCHAR(200)   NOT NULL,
    on_date  DATE           NOT NULL,
    due      DECIMAL(19, 2)
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id, id);
== V26__person_hold.sql
-- A hold is dated: it runs from its from-date to its to-date (none: open-ended), and a person may
-- have several over time. Only a person's OPEN claims dated within a hold count in no live total;
-- a claim bound by a statement still counts whatever its date. A person held before holds were
-- dated keeps a hold from the beginning of time.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    from_date DATE         NOT NULL,
    to_date   DATE,
    held_by   VARCHAR(200) NOT NULL,
    held_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX person_hold_person ON person_hold (sheet_id, person_id, id);
INSERT INTO person_hold (sheet_id, person_id, from_date, to_date, held_by)
    SELECT sheet_id, id, DATE '0001-01-01', NULL, created_by FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V27__rate_to.sql
-- A rate can carry a to-date: it applies through that date. A claim dated after the to-date of the
-- rate that would apply to it (the latest from-date on or before its date) has no rate. Null: no end.
ALTER TABLE rate ADD COLUMN to_date DATE;
== V28__period_person_total.sql
-- A closed period's figures per person: each person on the sheet when it was closed, with the due of
-- their claims that count dated in it, fixed at that moment. A person added later has none (0.00).
-- Removed when the period is reopened. The period's due-total is the sum of these.
CREATE TABLE period_person_total (
    period_id BIGINT        NOT NULL REFERENCES period (id),
    person_id BIGINT        NOT NULL REFERENCES person (id),
    total     DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
== V29__setting_from.sql
-- A setting that carries a figure is dated: each value saved applies from its from-date, a key may
-- have several (one per from-date), and the value in force on a date is the one with the latest
-- from-date on or before it. No from-date applies from the beginning of time: the values set before
-- settings were dated, and the undated keys (policy-date, period-numbering-from).
ALTER TABLE sheet_setting ADD COLUMN from_date DATE;
ALTER TABLE sheet_setting DROP PRIMARY KEY;
ALTER TABLE sheet_setting ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
CREATE UNIQUE INDEX sheet_setting_from ON sheet_setting (sheet_id, setting, from_key);
== V30__claim_deferred.sql
-- An OPEN claim deferred until a date after the sheet's today (none: not deferred). Until the sheet's
-- today reaches that date it counts in no total, is not overdue, cannot be settled and is left unbound
-- by a statement; from that day on it is an OPEN claim like any other.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== V31__claim_proofs.sql
-- How many proofs a claim has: raised by one at a time, while it is neither SETTLED nor VOID. A claim
-- whose due is above the proof threshold in force on its date cannot be settled or approved at 0.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
== V32__role_viewer.sql
-- A third role: a viewer sees everything on the sheet and may change nothing. The role check is
-- unnamed, so the table is rebuilt with the wider one.
CREATE TABLE sheet_role_new (
    sheet_id   VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name  VARCHAR(200) NOT NULL,
    role       VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer')),
    set_by     VARCHAR(200) NOT NULL,
    set_at     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (sheet_id, user_name)
);
INSERT INTO sheet_role_new (sheet_id, user_name, role, set_by, set_at)
    SELECT sheet_id, user_name, role, set_by, set_at FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;
== V33__claim_split_from.sql
-- The number of the claim a claim was split from (none for any other claim, and for the original
-- of a split).
ALTER TABLE claim ADD COLUMN split_from VARCHAR(220);
== V34__person_watch.sql
-- A user watches a person on a sheet, each user for themselves. A watch's id orders the watchers of a
-- person by when they started watching; stopping deletes it, so watching again starts a new one.
CREATE TABLE person_watch (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id  BIGINT       NOT NULL REFERENCES person (id),
    watched_by VARCHAR(200) NOT NULL,
    watched_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT person_watch_unique UNIQUE (sheet_id, person_id, watched_by)
);
CREATE INDEX person_watch_user ON person_watch (sheet_id, watched_by);
== V35__delegation.sql
-- A steward delegates the steward role to a user for a from-date to a to-date, inclusive, by the
-- sheet's today. While the sheet's today is inside the range the user acts as a steward in every rule,
-- and the audit lines of a change they make name the steward who delegated (for=).
CREATE TABLE delegation (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name    VARCHAR(200) NOT NULL,
    from_date    DATE         NOT NULL,
    to_date      DATE         NOT NULL,
    delegated_by VARCHAR(200) NOT NULL,
    delegated_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX delegation_user ON delegation (sheet_id, user_name);
== V36__sheet_archived.sql
-- A steward can archive a sheet: everything on it stays visible, and every change to it is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
== V37__person_terms.sql
-- A person may have their own terms (whole days; null: none): a claim's due-by is fixed at
-- creation from them, before the terms of their grade and the sheet's.
ALTER TABLE person ADD COLUMN terms INT;
== V38__claim_lock.sql
-- Opening a claim's editor locks it for other users (the user holding it; null: unlocked) until the
-- editor is saved or cancelled, or the sheet's today changes.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(200);
== V39__period_soft_close.sql
-- A soft-closed period: its due-total (closed_total) and each person's figure for it
-- (period_person_total) are fixed at the moment it was soft-closed, but claims dated inside it can
-- still be added and changed. It can then be closed (fixing the figures afresh) or reopened.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
-- A claim added while the period its date falls in was soft-closed.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
== V40__person_statement.sql
-- Each statement taken of a person, in the order taken: its due-total (text: two decimals, or n/a)
-- and date. Kept so a steward can cancel the last one and the person shows the one before it again.
-- A person stated before statements were kept keeps their last one (the earlier ones are not known).
CREATE TABLE person_statement (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id      BIGINT       NOT NULL REFERENCES person (id),
    stated_total   VARCHAR(30),
    statement_date DATE         NOT NULL,
    taken_at       TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX person_statement_person ON person_statement (sheet_id, person_id, id);
INSERT INTO person_statement (sheet_id, person_id, stated_total, statement_date)
    SELECT sheet_id, id, stated_total, statement_date FROM person WHERE statement_count > 0 AND statement_date IS NOT NULL;
== V41__statement_asof.sql
-- What the sheet held as of a date, so a statement can be taken as of it: each change is kept with
-- the sheet's today when it was made (on_date). A change made while the sheet's today was on or before
-- a date counts as of it; a later one does not. Rows kept before this history have no on_date: they
-- count as of every date.

-- The sheet's today when the person was added (none: added before it was kept).
ALTER TABLE person ADD COLUMN added_on DATE;
-- The sheet's today when the hold was added (none: added before it was kept).
ALTER TABLE person_hold ADD COLUMN added_on DATE;

-- Each claim as it stood after every change to it, oldest first.
CREATE TABLE claim_history (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    claim_id       BIGINT         NOT NULL REFERENCES claim (id),
    on_date        DATE,
    person_id      BIGINT         NOT NULL,
    amount         DECIMAL(19, 2) NOT NULL,
    claim_date     DATE           NOT NULL,
    status         VARCHAR(10)    NOT NULL,
    settled_due    DECIMAL(19, 2),
    stated         BOOLEAN        NOT NULL,
    stated_due     DECIMAL(19, 2),
    deferred_until DATE,
    due_by         DATE           NOT NULL
);
CREATE INDEX claim_history_claim ON claim_history (sheet_id, claim_id, id);
INSERT INTO claim_history (sheet_id, claim_id, on_date, person_id, amount, claim_date, status, settled_due,
        stated, stated_due, deferred_until, due_by)
    SELECT sheet_id, id, NULL, person_id, amount, claim_date, status, settled_due, stated, stated_due,
        deferred_until, due_by FROM claim;

-- Each rate set, oldest first (a later one with the same grade and from-date replaces it).
CREATE TABLE rate_history (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200)   NOT NULL,
    grade     VARCHAR(10)    NOT NULL,
    pct       DECIMAL(19, 2) NOT NULL,
    from_date DATE,
    to_date   DATE,
    from_key  DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01')),
    on_date   DATE
);
CREATE INDEX rate_history_sheet ON rate_history (sheet_id, grade, id);
INSERT INTO rate_history (sheet_id, grade, pct, from_date, to_date, on_date)
    SELECT sheet_id, grade, pct, from_date, to_date, NULL FROM rate;

-- Each setting value recorded, oldest first (a later one with the same key and from-date replaces it).
CREATE TABLE setting_history (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    setting   VARCHAR(200) NOT NULL,
    val       VARCHAR(200),
    from_date DATE,
    from_key  DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01')),
    on_date   DATE
);
CREATE INDEX setting_history_sheet ON setting_history (sheet_id, setting, id);
INSERT INTO setting_history (sheet_id, setting, val, from_date, on_date)
    SELECT sheet_id, setting, val, from_date, NULL FROM sheet_setting;

-- Each grade a person was given, oldest first (a later one with the same from-date replaces it).
CREATE TABLE person_grade_history (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL,
    grade     VARCHAR(10)  NOT NULL,
    from_date DATE,
    from_key  DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01')),
    on_date   DATE
);
CREATE INDEX person_grade_history_person ON person_grade_history (sheet_id, person_id, id);
INSERT INTO person_grade_history (sheet_id, person_id, grade, from_date, on_date)
    SELECT sheet_id, person_id, grade, from_date, NULL FROM person_grade;

-- Each retirement date a person was given, oldest first (the last one stands).
CREATE TABLE person_retired_history (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(200) NOT NULL,
    person_id    BIGINT       NOT NULL,
    retired_from DATE         NOT NULL,
    on_date      DATE
);
CREATE INDEX person_retired_history_person ON person_retired_history (sheet_id, person_id, id);
INSERT INTO person_retired_history (sheet_id, person_id, retired_from, on_date)
    SELECT sheet_id, id, retired_from, NULL FROM person WHERE retired_from IS NOT NULL;

