// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` tells a conflict (409) from a refusal. */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useQuery } from '@tanstack/react-query';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useSheetId, useUser } from '../session/session';
import { openSheet, sheetKey } from './api';
import { SheetToday } from './SheetToday';

/** The loaded sheet: its id, then everything kept on it (the sheet.body region). */
export function ActiveSheet() {
  const [user] = useUser();
  const [sheetId] = useSheetId();
  const sheet = useQuery({
    queryKey: sheetKey(sheetId),
    queryFn: () => openSheet(sheetId, user),
    enabled: sheetId !== '',
  });

  if (sheetId === '') return <p data-testid="home-empty">No sheet loaded.</p>;
  if (sheet.isError) return <p data-testid="sheet-error">The sheet could not be loaded.</p>;
  if (!sheet.data) return <p data-testid="sheet-loading">Loading…</p>;

  return (
    <section>
      <h2>
        Sheet <span data-testid="sheet-current-id">{sheet.data.id}</span>
      </h2>
      <SheetToday key={sheet.data.id} sheet={sheet.data} user={user} />
      <SheetBody.Slot sheetId={sheet.data.id} user={user} />
    </section>
  );
}
import { useQuery } from '@tanstack/react-query';
import { postJson } from '../../api/http';

/** `today` is the sheet's own date (yyyy-MM-dd): every date decision and default uses it.
 *  `archived`: a steward archived it; everything stays visible and every change is refused. */
export type Sheet = { id: string; createdBy: string; today: string; archived: boolean };

/** Load a sheet by id; the server starts it empty the first time the id is used. */
export function openSheet(id: string, by: string): Promise<Sheet> {
  return postJson<Sheet>(
    `/api/sheets/${encodeURIComponent(id)}/open?by=${encodeURIComponent(by)}`,
    {},
  );
}

/** Change the sheet's today; refused (rejects) when it is not a date. */
export function setSheetToday(id: string, by: string, today: string): Promise<Sheet> {
  return postJson<Sheet>(
    `/api/sheets/${encodeURIComponent(id)}/today?by=${encodeURIComponent(by)}`,
    { today },
  );
}

/** Archive the sheet; refused (rejects) for anyone but a steward, and when already archived. */
export function archiveSheet(id: string, by: string): Promise<Sheet> {
  return postJson<Sheet>(
    `/api/sheets/${encodeURIComponent(id)}/archive?by=${encodeURIComponent(by)}`,
    {},
  );
}

/** Every query about a sheet lives under this key, so loading it again re-reads all of it. */
export const sheetKey = (id: string) => ['sheet', id] as const;

/** The loaded sheet's today, read from the sheet query `ActiveSheet` keeps; '' until loaded. */
export function useSheetToday(id: string, by: string): string {
  const sheet = useQuery({ queryKey: sheetKey(id), queryFn: () => openSheet(id, by) });
  return sheet.data?.today ?? '';
}
import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { useSheetId } from '../session/session';
import { sheetKey } from './api';

/** Choose a sheet by typing its id and loading it. */
export function SheetPicker() {
  const queryClient = useQueryClient();
  const [, setSheetId] = useSheetId();
  const [id, setId] = useState('');
  const [error, setError] = useState(false);

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        const trimmed = id.trim();
        if (!trimmed) {
          setError(true);
          return;
        }
        // Loading a sheet re-reads it from the store, even when it was on screen before.
        queryClient.removeQueries({ queryKey: sheetKey(trimmed) });
        setSheetId(trimmed);
      }}
    >
      <label>
        Sheet{' '}
        <input
          data-testid="sheet-id-input"
          value={id}
          onChange={(e) => {
            setId(e.target.value);
            setError(false);
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-load">
        Load
      </button>
      {error && <span data-testid="sheet-load-error">Type a sheet id to load.</span>}
    </form>
  );
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError } from '../../api/http';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { archiveSheet, setSheetToday, sheetKey, type Sheet } from './api';

/** Whether a change was refused rather than invalid (the server answers 403: a viewer, an archived
 *  sheet, or archiving by anyone but a steward). */
function refused(error: Error | null): boolean {
  return error instanceof HttpError && error.status === 403;
}

/** The sheet's today, shown and changeable, and whether it is archived, with the button that archives
 *  it. Every date on the sheet goes by its today. The two share the sheet's one error element. */
export function SheetToday({ sheet, user }: { sheet: Sheet; user: string }) {
  const queryClient = useQueryClient();
  const [date, setDate] = useState('');
  const save = useMutation({
    mutationFn: (today: string) => setSheetToday(sheet.id, user, today),
    onSuccess: (updated) => {
      // Everything under the sheet may depend on its today: re-read it all.
      queryClient.setQueryData(sheetKey(sheet.id), updated);
      queryClient.invalidateQueries({
        queryKey: sheetKey(sheet.id),
        predicate: (q) => q.queryKey.length > 2,
      });
    },
  });

  const archive = useMutation({
    mutationFn: () => archiveSheet(sheet.id, user),
    onSuccess: (updated) => queryClient.setQueryData(sheetKey(sheet.id), updated),
  });

  const submitOnce = useSubmitOnce();

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        const today = date.trim();
        submitOnce(() => {
          save.reset();
          archive.reset();
          return save.mutateAsync(today);
        });
      }}
    >
      Today <span data-testid="sheet-today">{sheet.today}</span>{' '}
      <input
        type="date"
        data-testid="sheet-today-input"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          save.reset();
          archive.reset();
        }}
      />{' '}
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set today
      </button>
      Archived <span data-testid="sheet-archived">{sheet.archived ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="sheet-archive"
        disabled={archive.isPending}
        onClick={() => {
          save.reset();
          archive.reset();
          archive.mutate();
        }}
      >
        Archive
      </button>{' '}
      {save.isError && (
        <span data-testid="sheet-error">
          {refused(save.error) ? 'The sheet cannot be changed.' : 'That is not a date.'}
        </span>
      )}
      {archive.isError && (
        <span data-testid="sheet-error">
          Only a steward may archive the sheet, once.
        </span>
      )}
    </form>
  );
}
import { createFileRoute } from '@tanstack/react-router';
import { useUser } from '../features/session/session';
import { SignIn } from '../features/session/SignIn';
import { CurrentUser } from '../features/session/CurrentUser';
import { SheetPicker } from '../features/sheet/SheetPicker';
import { ActiveSheet } from '../features/sheet/ActiveSheet';

// The one screen. Sign in first; then choose a sheet, and everything else is on that sheet.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  const [user] = useUser();
  if (!user) return <SignIn />;
  return (
    <>
      <CurrentUser />
      <SheetPicker />
      <ActiveSheet />
    </>
  );
}
import { Outlet, createRootRouteWithContext } from '@tanstack/react-router';
import type { QueryClient } from '@tanstack/react-query';
import { AppNav } from '../slots/defs/appNav';

// The shell. It renders the nav region (filled from app.nav) and the matched route's component
// (from routes/); it reads no page list and holds no view state — URL search params carry what is
// open or filtered.
export const Route = createRootRouteWithContext<{ queryClient: QueryClient }>()({
  // Search params are an open namespace, declared once here and inherited by every route: a key is
  // used by reading/writing it (url/useSearchParam), with no per-key schema.
  validateSearch: (search: Record<string, unknown>) => search,
  component: AppShell,
});

function AppShell() {
  return (
    <div data-testid="app-root">
      <nav data-testid="app-nav">
        <AppNav.Slot />
      </nav>
      <main data-testid="app-home">
        <Outlet />
      </main>
    </div>
  );
}
import { QueryClient } from '@tanstack/react-query';

// Server data is NEVER copied into component state. A feature reads it with useQuery under its own
// key (e.g. ['clients'] / ['project', id, 'notes']) and changes it with useMutation +
// invalidateQueries. Two features share data by sharing a KEY, never by a parent holding it.
// retry:false + no focus refetching keep the e2e runs deterministic.
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: { retry: false, refetchOnWindowFocus: false },
    mutations: { retry: false },
  },
});

